-- Owner-supplied catalogue, 2026-10-23. Source SHA-256: 9f3228f704bb5eca2857dba54ef3f534eaedbed7697b4529158e8f05215e698d
-- Insert missing definitions without replacing administrator-owned names, activation or prices.
CREATE TEMP TABLE catalogue_roots(code TEXT, name TEXT, position INTEGER, illustration TEXT, icon TEXT, proposed_id UUID) ON COMMIT DROP;
CREATE TEMP TABLE catalogue_groups(root_code TEXT, code TEXT, name TEXT, position INTEGER, proposed_id UUID) ON COMMIT DROP;
CREATE TEMP TABLE catalogue_leaves(root_code TEXT, group_code TEXT, code TEXT, name TEXT, position INTEGER, proposed_id UUID) ON COMMIT DROP;

SELECT proposed_id, code, name, position, illustration, icon, 'catalogue-20261023', 'catalogue-20261023'
FROM catalogue_roots
ON CONFLICT (code) DO NOTHING;

SELECT seed.proposed_id, root.id, seed.code, seed.name, seed.position, 'catalogue-20261023', 'catalogue-20261023'
FROM catalogue_groups seed JOIN crm.border_tariff_category root ON root.code = seed.root_code
ON CONFLICT (category_id, code) DO NOTHING;

-- Reuse an exact existing terminal in the same root before inserting new identities.
-- A subsequent administrator reclassification is never overwritten.
UPDATE crm.border_tariff_subcategory terminal
SET group_id = destination.id, updated_by_subject = 'catalogue-20261023',
    updated_at = CURRENT_TIMESTAMP, version = terminal.version + 1
FROM catalogue_leaves seed
JOIN crm.border_tariff_category root ON root.code = seed.root_code
JOIN crm.border_tariff_category_group destination ON destination.category_id = root.id AND destination.code = seed.group_code
WHERE terminal.category_id = root.id AND terminal.code = seed.code AND terminal.display_name = seed.name
  AND terminal.deleted_at IS NULL
  AND EXISTS (SELECT 1 FROM crm.border_tariff_category_group old_parent WHERE old_parent.id = terminal.group_id AND old_parent.code = 'LEGACY')
  AND (SELECT count(*) FROM catalogue_leaves candidate WHERE candidate.root_code = seed.root_code AND candidate.code = seed.code) = 1
  AND NOT EXISTS (SELECT 1 FROM crm.border_tariff_subcategory existing WHERE existing.group_id = destination.id AND existing.code = seed.code AND existing.deleted_at IS NULL);

SELECT seed.proposed_id, root.id, parent.id, seed.code, seed.name, seed.position,
       'subcategory-' || lower(replace(seed.root_code || '-' || seed.group_code || '-' || seed.code, '_', '-')),
       'catalogue-20261023', 'catalogue-20261023'
FROM catalogue_leaves seed
JOIN crm.border_tariff_category root ON root.code = seed.root_code
JOIN crm.border_tariff_category_group parent ON parent.category_id = root.id AND parent.code = seed.group_code
ON CONFLICT (group_id, code) WHERE deleted_at IS NULL DO NOTHING;

-- No tariff minimums, transport costs or published policies are created or changed.
